def test_canonical_backbone_seeds_include_all_direct_changed_anchors() -> None:
    review_slice = ReviewSlice(
        change_map=CanonicalChangeMapEntry(
            focus_statement_id="R1",
            structural_overlay=StructuralFocusOverlay(
                nodes=(
                    StructuralFocusNode(
                        node_id="N:rg-primary",
                        role="changed_anchor",
                    ),
                    StructuralFocusNode(
                        node_id="N:rg-test",
                        role="changed_anchor",
                    ),
                    StructuralFocusNode(
                        node_id="N:rg-primary-context",
                        role="intermediate",
                    ),
                )
            ),
        )
    )
    transformation_group = TransformationStructuralTopologyGroup(
        claim_id="T1",
        structural_overlay=StructuralFocusOverlay(
            nodes=(
                StructuralFocusNode(
                    node_id="N:transformation-anchor",
                    role="changed_anchor",
                ),
                StructuralFocusNode(
                    node_id="N:transformation-context",
                    role="intermediate",
                ),
            )
        ),
    )

    assert _canonical_backbone_seed_node_ids(
        slices=(review_slice,),
        transformation_topology_groups=(transformation_group,),
    ) == ("N:rg-primary", "N:rg-test", "N:transformation-anchor")

def _canonical_backbone_seed_node_ids(
    *,
    slices: tuple[ReviewSlice, ...],
    transformation_topology_groups: tuple[
        TransformationStructuralTopologyGroup, ...
    ],
) -> tuple[str, ...]:
    """Map selected direct changed structural anchors onto one backbone."""

    seeds = []
    for review_slice in slices:
        seeds.extend(
            node.node_id
            for node in review_slice.change_map.structural_overlay.nodes
            if node.role == "changed_anchor"
        )
    for group in transformation_topology_groups:
        seeds.extend(
            node.node_id
            for node in group.structural_overlay.nodes
            if node.role == "changed_anchor"
        )
    return tuple(dict.fromkeys(seeds))
